VerilatedContext* contextp = NULL;
VerilatedFstC* tfp = NULL;
static MODULE_NAME* top;
#if defined(MODULE_YSYX_V3_TOPPROC_MINIRV)
static uint32_t exit_pc = 0, exit_a0 = 0;
#endif

// C implementation of add() for use in vsrc/dpi_c_example.v via DPI-C
int add(int a, int b) { return a+b; }

// Function Declarations
void step_and_dump_wave();
void sim_init(int argc, char** argv, const char* wave_file);
void sim_exit();

// Function Definitions
void step_and_dump_wave(){
  top->eval();
  contextp->timeInc(1);
  tfp->dump(contextp->time());
}
void sim_init(int argc, char** argv, const char* wave_file){
  contextp = new VerilatedContext;
  contextp->commandArgs(argc, argv);
  tfp = new VerilatedFstC;
  top = new MODULE_NAME{contextp};
  contextp->traceEverOn(true);
  top->trace(tfp, 99);
  tfp->open(wave_file);
}

void sim_exit(){
  // DPI callbacks run inside eval(): defer cleanup until eval() returns.
#if defined(MODULE_YSYX_V3_TOPPROC_MINIRV)
  exit_pc = top->debug_pc;
  exit_a0 = top->debug_regs[10];
#endif
  contextp->gotFinish(true);
}

void sim_cleanup(){
  top->final();
  tfp->close();
  delete top;
  delete tfp;
  delete contextp;
}

